import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';

import OneArticleBody from './OneArticleBody';
import { getOneArticleAsync } from '../@services/articles.service';
import { IArticle } from '../@types/articles.types';

interface IOneArticleProps {
  id: number;
  onDataReady?: (article: IArticle) => void;
}

const OneArticle = ({ id, onDataReady }: IOneArticleProps) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IArticle>();
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = await getOneArticleAsync(id);
        setData(d);
        onDataReady?.(d);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err}</PohAlert>;
  }

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  return (
    <article>
      <OneArticleBody text={data.text} />
    </article>
  );
};

export default OneArticle;
